using System.Text;
using HazukiPdf.Filters;
using HazukiPdf.Objects;
using HazukiPdf.Parsing;
using HazukiPdf.Security;

namespace HazukiPdf.Tests;

public class EncryptionTests
{
    // One-page files made with qpdf: content "(Hello encrypted world) Tj", title "Secret title",
    // owner password "owner", and an empty user password unless the name says otherwise.
    private static readonly Dictionary<string, string> Files = new()
    {
        ["Rc4_40"] = "",
        ["Rc4_128"] = "",
        ["Aes128"] = "",
        ["Aes256"] = "",
        ["Aes256UserPassword"] = "",
        ["Rc4UserPassword"] = "",
    };

    private static byte[] File(string name) => Convert.FromBase64String(Files[name]);

    private static (string Content, string Title) ReadBack(byte[] pdf, string? password = null)
    {
        var document = PdfReader.Read(pdf, password);
        var page = document.GetPages().Single().Page;
        var content = (PdfStream)document.Resolve(page.Get("Contents"))!;
        var text = Encoding.Latin1.GetString(StreamFilters.Decode(content.Data, StreamFilters.GetFilters(content, document.Resolve), strict: true));
        var info = (PdfDictionary)document.Resolve(document.Trailer.Get("Info"))!;
        return (text, ((PdfString)document.Resolve(info.Get("Title"))!).AsText());
    }

    [Theory]
    [InlineData("Rc4_40")]
    [InlineData("Rc4_128")]
    [InlineData("Aes128")]
    [InlineData("Aes256")]
    public void OpensFilesWithAnEmptyUserPassword(string name)
    {
        var (content, title) = ReadBack(File(name));
        Assert.Contains("(Hello encrypted world) Tj", content, StringComparison.Ordinal);
        Assert.Equal("Secret title", title);
    }

    [Theory]
    [InlineData("Aes256UserPassword")]
    [InlineData("Rc4UserPassword")]
    public void NeedsThePasswordWhenThereIsAUserPassword(string name)
    {
        Assert.Throws<PdfEncryptedException>(() => PdfReader.Read(File(name)));
        Assert.Throws<PdfEncryptedException>(() => PdfReader.Read(File(name), "wrong"));
        Assert.Equal("Secret title", ReadBack(File(name), "secret").Title);
        Assert.Equal("Secret title", ReadBack(File(name), "owner").Title);
    }

    [Fact]
    public void AnUnneededPasswordIsIgnored()
    {
        Assert.Equal("Secret title", ReadBack(File("Aes128"), "whatever").Title);
    }

    [Theory]
    [InlineData("Rc4_128")]
    [InlineData("Aes256")]
    public void CompressedOutputIsUnencryptedAndReadable(string name)
    {
        var output = PdfCompressor.Compress(File(name), PdfCompressionLevel.Maximum);
        Assert.DoesNotContain("/Encrypt", Encoding.Latin1.GetString(output), StringComparison.Ordinal);
        var (content, title) = ReadBack(output);
        Assert.Contains("Hello encrypted world", content, StringComparison.Ordinal);
        Assert.Equal("Secret title", title);
    }

    [Fact]
    public void PasswordOptionIsUsed()
    {
        var options = new PdfCompressionOptions { Password = "secret" };
        var output = PdfCompressor.Compress(File("Aes256UserPassword"), options);
        Assert.Equal("Secret title", ReadBack(output).Title);
    }

    [Fact]
    public void Rc4MatchesAKnownVector()
    {
        // RFC 6229-style check: key "Key", plaintext "Plaintext".
        var result = StandardSecurityHandler.Rc4(Encoding.ASCII.GetBytes("Key"), Encoding.ASCII.GetBytes("Plaintext"));
        Assert.Equal("BBF316E8D940AF0AD3", Convert.ToHexString(result));
    }
}
